	Tcl_DString cmdName;
	const char *p;
	int length;

	Tcl_DStringInit(&cmdName);
	Tcl_DStringAppend(&cmdName, "tcl::mathfunc::", -1);
	p = TclGetStringFromObj(*funcObjv, &length);
