    cmdPtr->u.native.delProc = delProc;
    cmdPtr->u.native.cmdProc = cmdProc;
    cmdPtr->u.native.usage = usage;
    cmdPtr->u.native.help = help;
    cmdPtr->u.native.minargs = minargs;
    cmdPtr->u.native.maxargs = maxargs;
