	string1 = NULL;
	length1 = Tcl_GetCharLength(objv[2]) - 1;
    }

    if ((TclGetIntForIndex(interp, objv[3], length1, &first) != TCL_OK)
	    || (TclGetIntForIndex(interp, objv[4], length1,
		    &last) != TCL_OK)) {
