{
    Object *oPtr = (Object *) Tcl_ObjectContextObject(context);
    Tcl_Size skip = Tcl_ObjectContextSkippedArgs(context);
    Tcl_Obj *cfgSupportName;
    Class *mixin;

    if (objc != skip && objc != skip + 1) {
